#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "3mm.h"


/* Array initialization. */
static
void init_array(int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl))
{
  int i, j;

  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / (5*ni);
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) ((i*(j+1)+2) % nj) / (5*nj);
  for (i = 0; i < nj; i++)
    for (j = 0; j < nm; j++)
      C[i][j] = (DATA_TYPE) (i*(j+3) % nl) / (5*nl);
  for (i = 0; i < nm; i++)
    for (j = 0; j < nl; j++)
      D[i][j] = (DATA_TYPE) ((i*(j+2)+2) % nk) / (5*nk);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nl,
		 DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("G");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, G[i][j]);
    }
  POLYBENCH_DUMP_END("G");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_3mm(int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(E,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(F,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl),
		DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j, k;

#pragma scop
#define BLOCK 32
  /* E := A*B */
  #pragma omp parallel default(shared)
  {
    #pragma omp for collapse(2) schedule(static) nowait
    for (int ii = 0; ii < _PB_NI; ii += BLOCK)
      for (int jj = 0; jj < _PB_NJ; jj += BLOCK)
        for (int kk = 0; kk < _PB_NK; kk += BLOCK)
        {
          int i_max = ii + BLOCK; if (i_max > _PB_NI) i_max = _PB_NI;
          int j_max = jj + BLOCK; if (j_max > _PB_NJ) j_max = _PB_NJ;
          int k_max = kk + BLOCK; if (k_max > _PB_NK) k_max = _PB_NK;
          for (int i = ii; i < i_max; ++i)
            for (int j = jj; j < j_max; ++j)
            {
              DATA_TYPE sum = (kk == 0) ? SCALAR_VAL(0.0) : E[i][j];
              #pragma omp simd reduction(+:sum)
              for (int k = kk; k < k_max; ++k)
                sum += A[i][k] * B[k][j];
              E[i][j] = sum;
            }
        }

    /* F := C*D */
    #pragma omp for collapse(2) schedule(static)
    for (int ii = 0; ii < _PB_NJ; ii += BLOCK)
      for (int jj = 0; jj < _PB_NL; jj += BLOCK)
        for (int kk = 0; kk < _PB_NM; kk += BLOCK)
        {
          int i_max = ii + BLOCK; if (i_max > _PB_NJ) i_max = _PB_NJ;
          int j_max = jj + BLOCK; if (j_max > _PB_NL) j_max = _PB_NL;
          int k_max = kk + BLOCK; if (k_max > _PB_NM) k_max = _PB_NM;
          for (int i = ii; i < i_max; ++i)
            for (int j = jj; j < j_max; ++j)
            {
              DATA_TYPE sum = (kk == 0) ? SCALAR_VAL(0.0) : F[i][j];
              #pragma omp simd reduction(+:sum)
              for (int k = kk; k < k_max; ++k)
                sum += C[i][k] * D[k][j];
              F[i][j] = sum;
            }
        }

    /* G := E*F */
    #pragma omp for collapse(2) schedule(static)
    for (int ii = 0; ii < _PB_NI; ii += BLOCK)
      for (int jj = 0; jj < _PB_NL; jj += BLOCK)
        for (int kk = 0; kk < _PB_NJ; kk += BLOCK)
        {
          int i_max = ii + BLOCK; if (i_max > _PB_NI) i_max = _PB_NI;
          int j_max = jj + BLOCK; if (j_max > _PB_NL) j_max = _PB_NL;
          int k_max = kk + BLOCK; if (k_max > _PB_NJ) k_max = _PB_NJ;
          for (int i = ii; i < i_max; ++i)
            for (int j = jj; j < j_max; ++j)
            {
              DATA_TYPE sum = (kk == 0) ? SCALAR_VAL(0.0) : G[i][j];
              #pragma omp simd reduction(+:sum)
              for (int k = kk; k < k_max; ++k)
                sum += E[i][k] * F[k][j];
              G[i][j] = sum;
            }
        }
  }
#undef BLOCK
#pragma endscop

}


